//! The embedded Typst typesetter.
//!
//! Topebag links the [Typst](https://typst.app) compiler as a library. Each
//! saved document is a tiny Typst "project" on disk:
//!
//! ```text
//! <entry>/
//!   main.typ        generated by [`main_source`]
//!   img/001.jpg …   images referenced by main.typ
//!   qr.svg          optional QR code for the masthead
//! ```
//!
//! plus the template `topebag.typ`, which is compiled into the binary and
//! served from memory. [`compile`] lays the project out into pages; from
//! there [`pdf`] produces the PDF that is saved in the library and
//! [`render_page`] rasterises pages for on-screen previews and printing.
//!
//! ## Fonts
//!
//! Fonts bundled with Typst (Libertinus Serif, New Computer Modern, DejaVu
//! Sans Mono) are always available, so output looks the same everywhere. On
//! Windows a curated set of system fonts is added for sans-serif text,
//! symbols, emoji and CJK/Indic scripts. Font files are only read when a
//! document actually uses them.

use std::collections::HashMap;
use std::fs;
use std::path::{Component, Path, PathBuf};
use std::sync::{Mutex, OnceLock};

use anyhow::{Result, anyhow};
use chrono::Datelike;
use typst::diag::{FileError, FileResult, SourceDiagnostic, Warned};
use typst::foundations::{Bytes, Datetime, Duration};
use typst::syntax::{FileId, RootedPath, Source, VirtualPath, VirtualRoot};
use typst::text::{Font, FontBook, FontInfo};
use typst::utils::LazyHash;
use typst::{Library, LibraryExt, World, WorldExt};
use typst_layout::PagedDocument;

use crate::convert::{breakable_url, string_literal};
use crate::settings::{Settings, Typeface};

/// The document template, compiled into the binary.
pub const TEMPLATE: &str = include_str!("../assets/topebag.typ");

/// Metadata printed in a document's masthead.
#[derive(Debug, Clone, Default)]
pub struct DocMeta {
    pub title: String,
    pub site_name: Option<String>,
    pub byline: Option<String>,
    pub published: Option<String>,
    pub url: Option<String>,
    pub lang: Option<String>,
    pub word_count: usize,
    /// When the document was saved (already formatted).
    pub saved: Option<String>,
    /// Whether a `qr.svg` exists next to `main.typ`.
    pub has_qr: bool,
}

/// Build the complete `main.typ` for an article.
///
/// `density` (0–1) tightens spacing; see [`compile_fitted`].
pub fn main_source(meta: &DocMeta, settings: &Settings, body: &str, density: f64) -> String {
    let opt = |v: &Option<String>| v.as_deref().map(string_literal).unwrap_or_else(|| "none".into());

    let mut meta_line = Vec::new();
    if let Some(byline) = &meta.byline {
        // Prefix "By" only when the byline looks like a list of names.
        let looks_like_names = !byline.chars().any(|c| c.is_ascii_digit()) && !byline.contains(['·', '|', '@']);
        let byline = if byline.to_lowercase().starts_with("by ") || !looks_like_names {
            byline.clone()
        } else {
            format!("By {byline}")
        };
        meta_line.push(byline);
    }
    if let Some(published) = &meta.published {
        meta_line.push(published.clone());
    }
    if meta.word_count >= 150 {
        meta_line.push(format!("{} min read", (meta.word_count as f64 / 230.0).round().max(1.0)));
    }
    let meta_array = if meta_line.is_empty() {
        "()".to_string()
    } else {
        format!("({},)", meta_line.iter().map(|s| string_literal(s)).collect::<Vec<_>>().join(", "))
    };

    let (lang, region) = split_lang(meta.lang.as_deref());
    let domain = meta
        .url
        .as_deref()
        .and_then(|u| url::Url::parse(u).ok())
        .and_then(|u| u.host_str().map(|h| h.trim_start_matches("www.").to_string()));
    let short_title = (meta.title.chars().count() > 80)
        .then(|| format!("{}…", meta.title.chars().take(78).collect::<String>().trim_end()));

    format!(
        r#"// Generated by Topebag {version}. Re-typesetting the entry regenerates this file.
#import "/topebag.typ": *
#show: tb-article.with(
  title: {title},
  short-title: {short_title},
  site: {site},
  meta: {meta_array},
  url: {url},
  url-display: {url_display},
  domain: {domain},
  saved: {saved},
  lang: {lang},
  region: {region},
  paper: {paper},
  font-size: {font_size}pt,
  typeface: {typeface},
  cols: {cols},
  justify: {justify},
  qr: {qr},
  spread: {spread},
  density: {density:.3},
)

{body}
"#,
        version = env!("CARGO_PKG_VERSION"),
        title = string_literal(&meta.title),
        short_title = opt(&short_title),
        site = opt(&meta.site_name),
        url = opt(&meta.url),
        url_display = meta.url.as_deref().map(|u| string_literal(&breakable_url(u))).unwrap_or_else(|| "none".into()),
        domain = opt(&domain),
        saved = opt(&meta.saved),
        lang = string_literal(&lang),
        region = region.as_deref().map(string_literal).unwrap_or_else(|| "none".into()),
        paper = string_literal(settings.paper.typst_name()),
        font_size = settings.font_size,
        typeface = string_literal(match settings.typeface {
            Typeface::Serif => "serif",
            Typeface::Sans => "sans",
        }),
        cols = settings.columns.clamp(1, 2),
        justify = settings.justify,
        qr = if meta.has_qr { "\"/qr.svg\"" } else { "none" },
        spread = settings.side_by_side,
        density = density.clamp(0.0, 1.0),
    )
}

/// Split `en-GB` into Typst's `lang: "en", region: "GB"`.
fn split_lang(tag: Option<&str>) -> (String, Option<String>) {
    let tag = tag.unwrap_or("en").trim();
    let mut parts = tag.split(['-', '_']);
    let lang = parts.next().unwrap_or("en").to_ascii_lowercase();
    let lang = if (2..=3).contains(&lang.len()) && lang.chars().all(|c| c.is_ascii_alphabetic()) {
        lang
    } else {
        "en".to_string()
    };
    let region = parts
        .next()
        .filter(|r| r.len() == 2 && r.chars().all(|c| c.is_ascii_alphabetic()))
        .map(|r| r.to_ascii_uppercase());
    (lang, region)
}

/// Generate an SVG QR code for `url`.
pub fn qr_svg(url: &str) -> Result<String> {
    use qrcode::render::svg;
    let code = qrcode::QrCode::with_error_correction_level(url.as_bytes(), qrcode::EcLevel::M)?;
    Ok(code
        .render::<svg::Color>()
        .min_dimensions(160, 160)
        .quiet_zone(false)
        .dark_color(svg::Color("#000000"))
        .light_color(svg::Color("#ffffff"))
        .build())
}

/// Basic facts about a PDF file.
#[derive(Debug, Clone)]
pub struct PdfInfo {
    pub pages: usize,
    pub title: Option<String>,
    pub author: Option<String>,
}

/// Read page count and metadata from PDF bytes.
pub fn pdf_info(bytes: &[u8]) -> Result<PdfInfo> {
    let pdf = hayro_syntax::Pdf::new(std::sync::Arc::new(bytes.to_vec())).map_err(|e| match e {
        hayro_syntax::LoadPdfError::Decryption(_) => anyhow!("this PDF is password-protected"),
        _ => anyhow!("this PDF could not be read (it may be damaged)"),
    })?;
    let pages = pdf.pages().len();
    if pages == 0 {
        return Err(anyhow!("this PDF has no pages"));
    }
    let meta = pdf.metadata();
    let text = |raw: &Option<Vec<u8>>| raw.as_deref().map(decode_pdf_string).filter(|t| !t.is_empty());
    let title = text(&meta.title).map(|t| t.trim_start_matches("Microsoft Word - ").to_string());
    Ok(PdfInfo { pages, title, author: text(&meta.author) })
}

/// PDF text strings are UTF-16BE (with a BOM) or PDFDocEncoding, which is
/// close enough to Latin-1 for titles.
fn decode_pdf_string(raw: &[u8]) -> String {
    let text = if let Some(utf16) = raw.strip_prefix(&[0xFE, 0xFF]) {
        let units: Vec<u16> = utf16.chunks_exact(2).map(|c| u16::from_be_bytes([c[0], c[1]])).collect();
        String::from_utf16_lossy(&units)
    } else if let Ok(utf8) = std::str::from_utf8(raw.strip_prefix(&[0xEF, 0xBB, 0xBF]).unwrap_or(raw)) {
        utf8.to_string()
    } else {
        raw.iter().map(|&b| b as char).collect()
    };
    text.chars().filter(|c| !c.is_control()).collect::<String>().split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Typst source that places every page of `/document.pdf` on a page of
/// its own size, for previewing and printing a downloaded PDF.
pub fn pdf_wrapper_source(pages: usize) -> String {
    format!(
        r#"// Generated by Topebag: shows the downloaded PDF page by page.
#set page(width: auto, height: auto, margin: 0pt, fill: white)
#for i in range(1, {pages} + 1) {{
  if i > 1 {{ pagebreak() }}
  block(image("/document.pdf", page: i))
}}
"#
    )
}

/// A laid-out article plus the source and spacing that produced it.
pub struct Fitted {
    pub compiled: Compiled,
    /// The `main.typ` that was compiled.
    pub source: String,
    /// How much spacing was tightened: 0 = normal, 1 = most compact.
    pub density: f64,
}

/// Binary-search steps for [`compile_fitted`] (1/64 ≈ 1.6 % precision).
const FIT_STEPS: usize = 6;
/// Stop refining after this long; very long articles take a while per pass.
const FIT_BUDGET: std::time::Duration = std::time::Duration::from_secs(20);

/// Lay out an article.
///
/// With side-by-side spreads and [`Settings::fit_to_sheets`], this finds the
/// *least* tightening that still yields the *fewest* sheets:
///
/// 1. lay out at density 0 (normal spacing) and at density 1 (most compact:
///    8.5 pt text, tight leading, narrow margins, smaller figures);
/// 2. if compact saves sheets, binary-search the smallest density that
///    keeps that sheet count.
///
/// So a 3-sheet article that can squeeze onto 2 sheets is tightened just
/// enough, while one that saves nothing keeps its normal spacing.
pub fn compile_fitted(meta: &DocMeta, settings: &Settings, body: &str, root: &Path) -> Result<Fitted> {
    let attempt = |density: f64| -> Result<Fitted> {
        let source = main_source(meta, settings, body, density);
        let compiled = compile(&source, root)?;
        Ok(Fitted { compiled, source, density })
    };

    let relaxed = attempt(0.0)?;
    if !(settings.side_by_side && settings.fit_to_sheets) || relaxed.compiled.page_count() <= 1 {
        return Ok(relaxed);
    }
    let started = std::time::Instant::now();
    let compact = match attempt(1.0) {
        Ok(compact) => compact,
        Err(_) => return Ok(relaxed),
    };
    let target = compact.compiled.page_count();
    if target >= relaxed.compiled.page_count() {
        return Ok(relaxed);
    }

    let mut lo = 0.0;
    let mut best = compact;
    for _ in 0..FIT_STEPS {
        if started.elapsed() > FIT_BUDGET {
            break;
        }
        let mid = (lo + best.density) / 2.0;
        match attempt(mid) {
            Ok(candidate) if candidate.compiled.page_count() <= target => best = candidate,
            _ => lo = mid,
        }
    }
    log::info!(
        "fitted to {} sheet(s) (from {}) at density {:.2} in {:?}",
        target,
        relaxed.compiled.page_count(),
        best.density,
        started.elapsed()
    );
    Ok(best)
}

/// A successfully laid-out document.
pub struct Compiled {
    pub document: PagedDocument,
    /// Non-fatal diagnostics (e.g. a missing fallback font).
    pub warnings: Vec<String>,
}

impl Compiled {
    pub fn page_count(&self) -> usize {
        self.document.pages().len()
    }
}

/// Lay out `main_typ`, resolving files (images, QR code) relative to `root`.
pub fn compile(main_typ: &str, root: &Path) -> Result<Compiled> {
    let world = ProjectWorld::new(main_typ, root);
    let Warned { output, warnings } = typst::compile::<PagedDocument>(&world);
    // Typst memoises aggressively; drop cache entries that weren't used in
    // the last few compilations so a long-running GUI doesn't grow forever.
    typst::comemo::evict(8);
    let warnings = warnings.iter().map(|w| describe(&world, w)).collect();
    match output {
        Ok(document) => Ok(Compiled { document, warnings }),
        Err(errors) => {
            let messages: Vec<String> = errors.iter().map(|e| describe(&world, e)).collect();
            Err(anyhow!("typesetting failed:\n{}", messages.join("\n")))
        }
    }
}

/// Compile the project stored in `root` (reads `root/main.typ`).
pub fn compile_dir(root: &Path) -> Result<Compiled> {
    let main = fs::read_to_string(root.join("main.typ"))
        .map_err(|e| anyhow!("could not read {}: {e}", root.join("main.typ").display()))?;
    compile(&main, root)
}

/// Export a laid-out document as PDF bytes.
pub fn pdf(doc: &PagedDocument) -> Result<Vec<u8>> {
    let options = typst_pdf::PdfOptions {
        creator: typst::foundations::Smart::Custom(Some(format!(
            "Topebag {} (Typst)",
            env!("CARGO_PKG_VERSION")
        ))),
        ..Default::default()
    };
    typst_pdf::pdf(doc, &options).map_err(|errors| {
        anyhow!(
            "PDF export failed: {}",
            errors.iter().map(|e| e.message.to_string()).collect::<Vec<_>>().join("; ")
        )
    })
}

/// A rasterised page in straight (non-premultiplied) RGBA8.
pub struct RasterPage {
    pub width: u32,
    pub height: u32,
    pub rgba: Vec<u8>,
}

/// Rasterise one page at `dpi` dots per inch on a white background.
pub fn render_page(doc: &PagedDocument, index: usize, dpi: f32) -> Option<RasterPage> {
    let page = doc.pages().get(index)?;
    let options = typst_render::RenderOptions {
        pixel_per_pt: typst::utils::Scalar::new(f64::from(dpi) / 72.0),
        render_bleed: false,
    };
    let pixmap = typst_render::render(page, &options);
    // Pages are opaque (white fill), so premultiplied == straight alpha.
    let (width, height) = (pixmap.width(), pixmap.height());
    Some(RasterPage { width, height, rgba: pixmap.take() })
}

/// Size of page `index` in points.
pub fn page_size_pt(doc: &PagedDocument, index: usize) -> Option<(f64, f64)> {
    let size = doc.pages().get(index)?.frame.size();
    Some((size.x.to_pt(), size.y.to_pt()))
}

/// Human-readable diagnostic with file/line context.
fn describe(world: &ProjectWorld, diag: &SourceDiagnostic) -> String {
    let mut msg = diag.message.to_string();
    if let Some(id) = diag.span.id() {
        if let (Ok(source), Some(range)) = (world.source(id), world.range(diag.span)) {
            let line = source.text()[..range.start].matches('\n').count() + 1;
            let line_text = source.text().lines().nth(line - 1).unwrap_or("").trim();
            let snippet: String = line_text.chars().take(120).collect();
            msg = format!("{}:{line}: {msg}  ⟶  {snippet}", id.vpath().get_without_slash());
        }
    }
    for hint in &diag.hints {
        msg.push_str(&format!(" (hint: {})", hint.v));
    }
    msg
}

// ---------------------------------------------------------------------------
// The Typst `World`: everything the compiler can see.
// ---------------------------------------------------------------------------

struct ProjectWorld {
    main: FileId,
    main_source: Source,
    template: Source,
    template_id: FileId,
    root: PathBuf,
    files: Mutex<HashMap<FileId, FileResult<Bytes>>>,
}

impl ProjectWorld {
    fn new(main_typ: &str, root: &Path) -> Self {
        let main = file_id("main.typ");
        let template_id = file_id("topebag.typ");
        Self {
            main,
            main_source: Source::new(main, main_typ.to_string()),
            template: Source::new(template_id, TEMPLATE.to_string()),
            template_id,
            root: root.to_path_buf(),
            files: Mutex::new(HashMap::new()),
        }
    }

    /// Map a virtual path to a real file below `root`, refusing anything
    /// that tries to escape it.
    fn real_path(&self, id: FileId) -> FileResult<PathBuf> {
        let rel = id.vpath().get_without_slash();
        let rel_path = Path::new(rel);
        if rel_path.components().any(|c| !matches!(c, Component::Normal(_))) {
            return Err(FileError::AccessDenied);
        }
        Ok(self.root.join(rel_path))
    }
}

fn file_id(path: &str) -> FileId {
    let vpath = VirtualPath::new(path).expect("static virtual path");
    RootedPath::new(VirtualRoot::Project, vpath).intern()
}

impl World for ProjectWorld {
    fn library(&self) -> &LazyHash<Library> {
        static LIBRARY: OnceLock<LazyHash<Library>> = OnceLock::new();
        LIBRARY.get_or_init(|| LazyHash::new(Library::default()))
    }

    fn book(&self) -> &LazyHash<FontBook> {
        &fonts().book
    }

    fn main(&self) -> FileId {
        self.main
    }

    fn source(&self, id: FileId) -> FileResult<Source> {
        if id == self.main {
            Ok(self.main_source.clone())
        } else if id == self.template_id {
            Ok(self.template.clone())
        } else {
            Err(FileError::NotSource)
        }
    }

    fn file(&self, id: FileId) -> FileResult<Bytes> {
        if id == self.main {
            return Ok(Bytes::from_string(self.main_source.text().to_string()));
        }
        if id == self.template_id {
            return Ok(Bytes::from_string(TEMPLATE));
        }
        let mut cache = self.files.lock().expect("file cache poisoned");
        cache
            .entry(id)
            .or_insert_with(|| {
                let path = self.real_path(id)?;
                fs::read(&path).map(Bytes::new).map_err(|e| FileError::from_io(e, &path))
            })
            .clone()
    }

    fn font(&self, index: usize) -> Option<Font> {
        fonts().get(index)
    }

    fn today(&self, offset: Option<Duration>) -> Option<Datetime> {
        let now = match offset {
            None => chrono::Local::now().naive_local(),
            Some(o) => (chrono::Utc::now() + chrono::Duration::seconds(o.seconds() as i64)).naive_utc(),
        };
        Datetime::from_ymd(now.year(), now.month() as u8, now.day() as u8)
    }
}

// ---------------------------------------------------------------------------
// Fonts
// ---------------------------------------------------------------------------

enum FontSource {
    Static(&'static [u8]),
    File(PathBuf),
}

struct FontSlot {
    source: FontSource,
    index: u32,
    font: OnceLock<Option<Font>>,
}

struct FontStore {
    book: LazyHash<FontBook>,
    slots: Vec<FontSlot>,
}

impl FontStore {
    fn get(&self, index: usize) -> Option<Font> {
        let slot = self.slots.get(index)?;
        slot.font
            .get_or_init(|| {
                let bytes = match &slot.source {
                    FontSource::Static(data) => Bytes::new(*data),
                    FontSource::File(path) => Bytes::new(fs::read(path).ok()?),
                };
                Font::new(bytes, slot.index)
            })
            .clone()
    }
}

/// Windows system fonts worth having: a sans-serif family, a serif and a
/// monospace alternative, symbols/emoji, and coverage for major scripts.
#[cfg(windows)]
const SYSTEM_FONTS: &[&str] = &[
    "segoeui.ttf", "segoeuib.ttf", "segoeuii.ttf", "segoeuiz.ttf", "seguisb.ttf",
    "georgia.ttf", "georgiab.ttf", "georgiai.ttf", "georgiaz.ttf",
    "consola.ttf", "consolab.ttf", "consolai.ttf", "consolaz.ttf",
    "seguisym.ttf", "seguiemj.ttf",
    "msyh.ttc", "msyhbd.ttc", "msjh.ttc", "YuGothR.ttc", "YuGothB.ttc", "malgun.ttf", "malgunbd.ttf",
    "Nirmala.ttc", "Nirmala.ttf", "ebrima.ttf", "arial.ttf", "arialbd.ttf",
];

fn fonts() -> &'static FontStore {
    static STORE: OnceLock<FontStore> = OnceLock::new();
    STORE.get_or_init(|| {
        let mut book = FontBook::new();
        let mut slots = Vec::new();

        for data in typst_assets::fonts() {
            for (index, info) in FontInfo::iter(data).enumerate() {
                book.push(info);
                slots.push(FontSlot { source: FontSource::Static(data), index: index as u32, font: OnceLock::new() });
            }
        }

        for path in system_font_paths() {
            let Ok(data) = fs::read(&path) else { continue };
            for (index, info) in FontInfo::iter(&data).enumerate() {
                book.push(info);
                slots.push(FontSlot {
                    source: FontSource::File(path.clone()),
                    index: index as u32,
                    font: OnceLock::new(),
                });
            }
        }

        FontStore { book: LazyHash::new(book), slots }
    })
}

fn system_font_paths() -> Vec<PathBuf> {
    #[cfg(windows)]
    {
        let windir = std::env::var_os("WINDIR").map(PathBuf::from).unwrap_or_else(|| PathBuf::from(r"C:\Windows"));
        let fonts = windir.join("Fonts");
        SYSTEM_FONTS.iter().map(|f| fonts.join(f)).filter(|p| p.exists()).collect()
    }
    #[cfg(not(windows))]
    {
        let candidates = [
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
            "/System/Library/Fonts/Helvetica.ttc",
            "/System/Library/Fonts/Supplemental/Arial.ttf",
        ];
        candidates.iter().map(PathBuf::from).filter(|p| p.exists()).collect()
    }
}

/// Load fonts in the background so the first document typesets faster.
pub fn warm_up() {
    std::thread::spawn(|| {
        let _ = fonts();
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_main(body: &str) -> String {
        let meta = DocMeta {
            title: "A \"quoted\" #title".into(),
            site_name: Some("Example".into()),
            byline: Some("Ada".into()),
            url: Some("https://example.com/a/very/long/path?with=query&and=more".into()),
            word_count: 900,
            saved: Some("5 November 2026".into()),
            ..Default::default()
        };
        main_source(&meta, &Settings::default(), body, 0.0)
    }

    #[test]
    fn compiles_a_document_to_pdf_and_pixels() {
        let dir = tempfile::tempdir().unwrap();
        let body = r#"Hello *not bold* \#tag. #heading(level: 2)[Part] Some text.

#list([one], [two])

#raw(block: true, lang: "rust", "fn main() {}")

#tb-table(columns: 2, [a], [b], [c], [d])

#quote(block: true)[Quoted]

#tb-rule()"#;
        let compiled = compile(&sample_main(body), dir.path()).unwrap();
        assert!(compiled.page_count() >= 1);

        let pdf = pdf(&compiled.document).unwrap();
        assert!(pdf.starts_with(b"%PDF"));

        let page = render_page(&compiled.document, 0, 36.0).unwrap();
        assert_eq!(page.rgba.len(), (page.width * page.height * 4) as usize);
        // The page is mostly white, but not entirely (there is text on it).
        assert!(page.rgba.iter().any(|&b| b < 128));
    }

    #[test]
    fn reports_errors_with_context() {
        let dir = tempfile::tempdir().unwrap();
        let err = compile(&sample_main("#nonexistent-function()"), dir.path()).err().unwrap();
        let msg = format!("{err:#}");
        assert!(msg.contains("main.typ"), "{msg}");
        assert!(msg.contains("nonexistent"), "{msg}");
    }

    #[test]
    fn refuses_to_read_outside_the_project() {
        let dir = tempfile::tempdir().unwrap();
        let err = compile(&sample_main(r#"#image("/../secret.png")"#), dir.path());
        assert!(err.is_err());
    }

    #[test]
    fn pdfs_round_trip_through_the_wrapper() {
        // Make a 2-page PDF with Typst itself, then wrap it like a download.
        let dir = tempfile::tempdir().unwrap();
        let source = "#set document(title: \"Two pages\")\n#set page(width: 300pt, height: 200pt)\nOne\n#pagebreak()\nTwo";
        let original = pdf(&compile(source, dir.path()).unwrap().document).unwrap();
        let info = pdf_info(&original).unwrap();
        assert_eq!(info.pages, 2);
        assert_eq!(info.title.as_deref(), Some("Two pages"));

        std::fs::write(dir.path().join("document.pdf"), &original).unwrap();
        let wrapped = compile(&pdf_wrapper_source(info.pages), dir.path()).unwrap();
        assert_eq!(wrapped.page_count(), 2);
        let (w, h) = page_size_pt(&wrapped.document, 0).unwrap();
        assert!((w - 300.0).abs() < 1.0 && (h - 200.0).abs() < 1.0, "pages keep their size: {w}x{h}");
        assert!(pdf_info(b"not a pdf").is_err());
    }

    fn long_body(paragraphs: usize) -> String {
        let para = "Paper never needs charging and never asks for an update. ".repeat(12);
        (0..paragraphs).map(|i| format!("#heading(level: 2)[Part {i}]\n\n{para}")).collect::<Vec<_>>().join("\n\n")
    }

    fn spread_meta() -> DocMeta {
        DocMeta { title: "Spread test".into(), url: Some("https://example.com/x".into()), ..Default::default() }
    }

    #[test]
    fn side_by_side_sheets_are_landscape() {
        let dir = tempfile::tempdir().unwrap();
        let settings = Settings { side_by_side: true, ..Settings::default() };
        let compiled = compile(&main_source(&spread_meta(), &settings, &long_body(3), 0.0), dir.path()).unwrap();
        let (w, h) = page_size_pt(&compiled.document, 0).unwrap();
        assert!(w > h, "landscape sheet expected, got {w}x{h}");
    }

    #[test]
    fn fitting_uses_the_fewest_sheets_with_the_least_tightening() {
        let dir = tempfile::tempdir().unwrap();
        let settings = Settings { side_by_side: true, fit_to_sheets: true, ..Settings::default() };
        let meta = spread_meta();
        let sheets_at = |paragraphs: usize, density: f64| {
            compile(&main_source(&meta, &settings, &long_body(paragraphs), density), dir.path()).unwrap().page_count()
        };

        // Find a length where compact layout saves a sheet.
        let paragraphs = (4..60)
            .step_by(2)
            .find(|&n| sheets_at(n, 1.0) < sheets_at(n, 0.0))
            .expect("some length must benefit from tightening");
        let fitted = compile_fitted(&meta, &settings, &long_body(paragraphs), dir.path()).unwrap();
        assert_eq!(fitted.compiled.page_count(), sheets_at(paragraphs, 1.0), "fewest sheets");
        assert!(fitted.density > 0.0 && fitted.density <= 1.0);
        // Slightly less tightening would cost a sheet (search precision 1/64).
        let looser = (fitted.density - 0.05).max(0.0);
        assert!(sheets_at(paragraphs, looser) > fitted.compiled.page_count() || looser == 0.0);
        assert!(fitted.source.contains("spread: true"));

        // A one-sheet article is left alone.
        let short = compile_fitted(&meta, &settings, &long_body(1), dir.path()).unwrap();
        assert_eq!(short.density, 0.0);

        // Fitting is off when not side by side.
        let normal = Settings { side_by_side: false, ..settings.clone() };
        assert_eq!(compile_fitted(&meta, &normal, &long_body(paragraphs), dir.path()).unwrap().density, 0.0);
    }

    #[test]
    fn qr_codes_are_svg() {
        assert!(qr_svg("https://example.com").unwrap().contains("<svg"));
    }

    #[test]
    fn splits_language_tags() {
        assert_eq!(split_lang(Some("en-GB")), ("en".into(), Some("GB".into())));
        assert_eq!(split_lang(Some("zh_Hant_TW")), ("zh".into(), None));
        assert_eq!(split_lang(Some("klingon!")), ("en".into(), None));
        assert_eq!(split_lang(None), ("en".into(), None));
    }
}
